$all=projectList();$public=in_array($role,['public','resident'],true);$selected=null;
if(isset($_GET['id']))foreach($all as $candidate)if((int)$candidate['id']===(int)$_GET['id'])$selected=$candidate;
if($public):
$q=is_string($_GET['q']??null)?trim($_GET['q']):'';$year=is_string($_GET['year']??null)?$_GET['year']:'';$status=is_string($_GET['status']??null)?$_GET['status']:'';
$ps=array_filter($all,fn($p)=>($q==='' || stripos($p['title'].' '.$p['description'],$q)!==false) && ($year==='' || substr($p['start_date'],0,4)===$year) && ($status==='' || $p['status']===$status));$years=[];foreach($all as $p)$years[substr($p['start_date'],0,4)]=substr($p['start_date'],0,4);krsort($years);
?>
<p class="muted">Browse approved SK projects and check their current status and details.</p><section class="panel"><form method="get" class="filters"><input type="hidden" name="page" value="projects"><?php field('Search Projects','q',$q,'search',false);selectField('Year','year',[''=>'All Years']+$years,$year,false);selectField('Status','status',[''=>'All Status','Pending'=>'Pending','Ongoing'=>'Ongoing','Completed'=>'Completed','Cancelled'=>'Cancelled'],$status,false); ?><button>Apply</button><a class="button secondary" href="<?= e(url('projects')) ?>">Reset</a></form><div class="table-wrap" tabindex="0" role="region" aria-label="Scrollable records"><table><thead><tr><th>Project Name</th><th>Description</th><th>Status</th><th>Details</th></tr></thead><tbody><?php foreach($ps as $p): ?><tr><td><?= e($p['title']) ?></td><td><?= e($p['description']) ?></td><td><?= badge($p['status']) ?></td><td><a class="button small secondary" href="<?= e(url('projects',['id'=>$p['id']])) ?>">View Details</a></td></tr><?php endforeach;if(!$ps)emptyRow(4,'No published projects match your filters.'); ?></tbody></table></div></section><?php if($selected)projectDetail($selected); ?>
<?php elseif($role==='official'): ?>
<div class="grid two"><div><section class="panel"><div class="section-heading"><h2>New Proposal</h2><a class="button small" href="<?= e(url('projects',['edit'=>'new'])) ?>">+ Add Proposal</a></div><?php $pending=array_filter($all,fn($p)=>$p['review_status']!=='Approved');foreach($pending as $p){projectCard($p);echo '<p>'.badge($p['review_status']).' <a href="'.e(url('projects',['edit'=>$p['id']])).'">Edit proposal</a></p>';}if(!$pending)echo '<p class="empty">No pending proposals.</p>'; ?></section><section class="panel"><h2>Suggested Proposals</h2><p class="muted">References from completed public projects in recorded history. These support your decisions; no automatic approval is implied.</p><?php $suggested=rows("SELECT p.*,c.name category FROM projects p JOIN categories c ON c.id=p.category_id WHERE p.published=1 AND p.status='Completed' ORDER BY p.end_date DESC LIMIT 5");foreach($suggested as $p): ?><article><h3><?= e($p['title']) ?></h3><p><?= e($p['category']) ?> · Completed <?= e($p['end_date']) ?> · Recorded budget <?= money($p['budget_cents']) ?></p></article><?php endforeach;if(!$suggested)echo '<p class="empty">Recommendations will appear after completed projects are published.</p>'; ?></section></div><section class="panel"><h2>Progress</h2><?php $approved=array_filter($all,fn($p)=>$p['review_status']==='Approved');foreach($approved as $p){projectCard($p);echo '<p><a href="'.e(url('projects',['id'=>$p['id']])).'">Update progress</a> · <a href="'.e(url('projects',['edit'=>$p['id']])).'">Edit details</a></p>';}if(!$approved)echo '<p class="empty">Approved projects will appear here.</p>'; ?></section></div>
<?php if(isset($_GET['edit'])):$edit=null;foreach($all as $p)if((int)$p['id']===(int)$_GET['edit'])$edit=$p;if($_GET['edit']==='new' || $edit): ?>
<section class="panel"><h2><?= $edit?'Edit Project / Activity':'New Project Proposal' ?></h2><p class="note">Changes require Chairperson review before public viewing. Financial totals are recorded by the Treasurer.</p><form method="post" enctype="multipart/form-data"><?php actionFields('save_project'); ?><input type="hidden" name="id" value="<?= e($edit['id']??0) ?>"><?php field('Project Title','title',$edit['title']??'','text',true,'maxlength="190"');textarea('Description','description',$edit['description']??'',true,10000); ?><div class="grid three"><?php selectField('Category','category_id',options('categories'),$edit['category_id']??'');selectField('Fund Source','source_id',options('fund_sources'),$edit['source_id']??'');field('Planned Amount (PHP)','planned_amount',isset($edit['planned_cents'])?number_format($edit['planned_cents']/100,2,'.',''):'0.00','number',true,'min="0" step="0.01"');field('Start Date','start_date',$edit['start_date']??'','date');field('End Date','end_date',$edit['end_date']??'','date');field('Location / Area','location',$edit['location']??'','text',true,'maxlength="190"');field('Implementing Committee','committee',$edit['committee']??'','text',true,'maxlength="190"');field('Target Beneficiaries','beneficiaries',$edit['beneficiaries']??'','text',true,'maxlength="255"');field('Beneficiary Count','beneficiary_count',$edit['beneficiary_count']??0,'number',true,'min="0" max="10000000"'); ?></div><?php field('Project Photo (optional; maximum 5 MB)','project_photo','','file',false,'accept="image/jpeg,image/png,image/webp"'); ?><div class="actions"><a class="button secondary" href="<?= e(url('projects')) ?>">Cancel</a><button>Submit for Review</button></div></form>
<?php if($edit && $edit['review_status']==='Pending'): ?><form method="post" data-confirm="Delete this pending proposal? Projects with financial or progress history will be retained."><?php actionFields('delete_project'); ?><input type="hidden" name="id" value="<?= e($edit['id']) ?>"><button class="danger small">Delete Pending Proposal</button></form><?php endif ?></section>
<?php endif;endif;if($selected):projectDetail($selected); ?>
<section class="panel"><h2>Update Project Progress</h2><p class="note">Saving a progress update removes the project from public viewing until the Chairperson reviews it again.</p><form method="post"><?php actionFields('progress'); ?><input type="hidden" name="project_id" value="<?= e($selected['id']) ?>"><div class="grid two"><?php selectField('Status','status',['Pending'=>'Pending','Ongoing'=>'Ongoing','Completed'=>'Completed','Cancelled'=>'Cancelled'],$selected['status']);field('Progress (%)','progress',$selected['progress'],'number',true,'min="0" max="100"'); ?></div><?php textarea('Update / Remarks','details'); ?><button>Save Progress</button></form><?php if($selected['remarks']!==''): ?><h3>Chairperson Remarks</h3><p><?= e($selected['remarks']) ?></p><?php endif ?></section>
<?php endif ?>
<?php else:allow(['chairperson']); ?>
<section class="panel"><form method="get" class="filters"><input type="hidden" name="page" value="<?= e($page) ?>"><?php selectField('Choose Project','id',array_column($all,'title','id'),$selected['id']??''); ?><button>View</button></form><div class="table-wrap" tabindex="0" role="region" aria-label="Scrollable records"><table><thead><tr><th>Project</th><th>Submitted By</th><th>Review</th><th>Public Viewing</th><th>Action</th></tr></thead><tbody><?php foreach($all as $p): ?><tr><td><?= e($p['title']) ?></td><td><?= e($p['owner']) ?></td><td><?= badge($p['review_status']) ?></td><td><?= $p['published']?'Published':($p['publication_requested']?'Awaiting review':'Private') ?></td><td><a href="<?= e(url($page,['id'=>$p['id']])) ?>">View</a></td></tr><?php endforeach;if(!$all)emptyRow(5); ?></tbody></table></div></section>
<?php if($selected):if($page==='proposals'): ?>
<section class="panel"><h2><?= e($selected['title']) ?></h2><h3>Project / Financial Information</h3><div class="grid three"><div><h3>Approved Budget</h3><?= money($selected['budget_cents']) ?></div><div><h3>Planned Amount</h3><?= money($selected['planned_cents']) ?></div><div><h3>Total Expense</h3><?= money($selected['spent']) ?></div><div><h3>Fund Source</h3><?= e($selected['source']) ?></div><div><h3>Start Date</h3><?= e($selected['start_date']) ?></div><div><h3>End Date</h3><?= e($selected['end_date']) ?></div><div><h3>Location / Area</h3><?= e($selected['location']) ?></div><div><h3>Committee</h3><?= e($selected['committee']) ?></div><div><h3>Submitted By</h3><?= e($selected['owner']) ?></div></div><p class="prewrap"><?= e($selected['description']) ?></p><form method="post"><?php actionFields('review_project'); ?><input type="hidden" name="id" value="<?= e($selected['id']) ?>"><?php textarea('Additional Remarks','remarks',$selected['remarks'],false);selectField('Review Decision','decision',['Approve'=>'Approve Proposal','Reject'=>'Reject Proposal','Publish'=>'Approve Public Viewing','Unpublish'=>'Remove from Public Viewing']); ?><button>Save Review</button></form><p class="note">Proposal approval, public publication and financial approvals are separate actions. Fund amounts are changed only through the fund request workflow.</p></section>
<?php else: ?>
<section class="panel"><h2><?= e($selected['title']) ?></h2><div class="grid three"><div><h3>Status</h3><?= badge($selected['status']) ?></div><div><h3>Implementing Committee</h3><?= e($selected['committee']) ?></div><div><h3>Approved Budget</h3><?= money($selected['budget_cents']) ?></div></div></section><div class="grid two"><section class="panel"><h2>Status</h2><?= badge($selected['status']) ?><h3>Project Progress</h3><progress max="100" value="<?= e($selected['progress']) ?>"><?= e($selected['progress']) ?>%</progress><p><?= e($selected['progress']) ?>%</p></section><section class="panel"><h2>Progress Log</h2><div class="table-wrap" tabindex="0" role="region" aria-label="Scrollable records"><table><thead><tr><th>Date &amp; Time</th><th>Status</th><th>Update / Remarks</th></tr></thead><tbody><?php $logs=rows('SELECT * FROM progress_logs WHERE project_id=? ORDER BY id DESC',[$selected['id']]);foreach($logs as $l): ?><tr><td><?= e($l['created_at']) ?></td><td><?= badge($l['status']) ?></td><td><?= e($l['details']) ?></td></tr><?php endforeach;if(!$logs)emptyRow(3); ?></tbody></table></div></section></div>
<?php endif;endif;endif ?>
